import json,hashlib
from pathlib import Path
root=Path(__file__).resolve().parents[2];audit=root/'Examtopics/audit'
qs=json.loads((root/'Examtopics/output/complete_q1_q1396.json').read_text(encoding='utf-8'))
by={q['id']:q for q in qs};fp=lambda q:hashlib.sha256(json.dumps(q,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
data={
941:('帧交换不一定是存储转发；限定方法并纠正校验和泛洪绝对化。',{'prompt':'Which characteristic describes store-and-forward Ethernet switching?', 'explanation':'C。存储转发交换机先接收完整帧并检查 FCS，再转发有效帧；CRC 可检测许多差错但不保证检测所有差错。也有 cut-through 等转发方式，不能将此过程归为所有帧交换的必然特征。A 混淆 ARP 与从入站帧源 MAC 学习的地址表；B 未知目的单播通常在同 VLAN 的合格端口泛洪，但安全策略等可能限制；D 普通二层转发不以重写源、目的 MAC 为职责。'}),
942:('原图第四行的句点导致整段无效 JSON，但可识别目标字符串值。',{'prompt':'Refer to the exhibit. In the intended JSON structure, what role does "R20" have? Note that the period after the last object must be removed for valid JSON.', 'explanation':'A。第 3 行 `"router": "R20"` 中，`router` 是键，`R20` 是对应字符串值；外层方括号表示数组，花括号包围对象。原图第 4 行对象后面的句点不是合法 JSON，应删除该句点才能解析整个数组。'}),
943:('补充同一 STP 实例及 BPDU 连通前提，按优先级和 MAC 比较。',{'prompt':'Refer to the exhibit. Assuming all four switches participate in the same STP instance and exchange BPDUs, which switch becomes root bridge?', 'explanation':'D。相同实例中比较桥 ID，首先比较优先级：SW1 和 SW4 的 12288 小于 SW2/SW3 的 28672；二者优先级相同时比较 MAC，SW4 的 `00:10:a1:03:42:e8` 小于 SW1 的 `00:10:a1:95:2b:77`，因此 SW4 胜出。该结论依赖各交换机同属选举域且能交换 BPDU。'}),
944:('修正端口冲突域、交换顺序及泛洪的过度概括。',{'explanation':'D。二层交换机在数据链路层处理并转发帧，通常根据 VLAN 和目的 MAC 查转发表。A 的端到端可靠有序交付由 TCP 等机制提供；B 的“使用路由器创建冲突域”不是交换机的基本定义；C 错，交换机会学习并保存源 MAC 与端口的对应关系。以太网全双工链路不发生 CSMA/CD 碰撞；不同 VLAN 可以形成独立广播域。'}),
945:('直接查看接口输出；区分瞬时队列与历史丢包，不能仅凭计数判定根因。',{'prompt':'Refer to the exhibit. Which condition is directly shown by the nonzero input and output queue sizes?', 'explanation':'B。图中 `Input queue: 175/300/0/0`、`Output queue: 50/300` 显示采样时队列中分别有 175、50 个包，`Queueing strategy: fifo` 表示采用 FIFO 策略；`Total output drops: 100` 是自计数器清零以来累计丢包，不能独立确定当前根因或持续拥塞。267 个广播是累计值，并不足以证明或排除风暴；图中错误计数为零也不能证明网卡或双工一定无故障。'}),
946:('对象也是 JSON value，限定更具体结构类型；原图存在句点与缺冒号。',{'prompt':'Refer to the exhibit. After correcting the punctuation errors, which specific JSON structural type is the curly-braced item on line 3?', 'explanation':'A。第 3 行最具体的结构类型是 object，位于顶层 array 中；object 同时也是一种 JSON value，因此题目限定为具体结构类型以消除 A/C 的歧义。原图第 2 行对象后为句点，应改成逗号；第 3 行 `"port"` 与 `"te0/26"` 之间缺少冒号。修正后示例：`{"load balancer": "LB_munich", "port": "te0/26"}`。'}),
947:('说明学习的是源 MAC 与 VLAN、入口端口；未知单播泛洪存在安全例外。',{'explanation':'D。交换机从进入帧的源 MAC 学习或更新对应的 VLAN 和入口端口；后续转发通常依据目的 MAC 和 VLAN 查表。MAC 移动时条目可更新，动态条目可老化。A 是可能配置的端口安全限制，而非 MAC 学习固有的 10 地址上限；B 并非学习机制的目标；C 混淆源地址学习和未知目的单播，后者通常向同 VLAN 合格端口泛洪，但可能受安全策略等限制。'}),
948:('A 原称所有 VLAN 与接口始终启用过于绝对，明确正常二层接口及功能默认状态。',{'prompt':'On a typical Cisco Ethernet switch with default MAC-learning settings, how does dynamic MAC learning operate on eligible active Layer 2 ports?', 'options':[{'label':'A','text':'It learns source MAC addresses on eligible VLANs and ingress ports by default.'},{'label':'B','text':'It increases security on the management VLAN by authenticating all senders.'},{'label':'C','text':'It sends all frames with unknown destinations to a multicast group.'},{'label':'D','text':'It automatically drops every frame whose destination is unknown.'}], 'explanation':'A。通常默认在支持学习的活跃二层端口和 VLAN 中，从进入帧的源 MAC 学习地址与端口的关联；学习可能受配置、端口状态和平台能力影响，不能断言任意接口与 VLAN 都一定学习。B 不是身份认证；C 将未知单播误认为组播；D 错，未知单播一般在同 VLAN 合格端口泛洪，但安全策略可能改变行为。'}),
949:('区分 VLAN 广播域以及未知单播、组播的不同转发处理。',{'prompt':'Which characteristic describes how a Layer 2 Ethernet switch normally makes forwarding decisions, regardless of how many VLANs are configured?', 'explanation':'D。二层交换机通常按 VLAN 与目的 MAC 地址查转发表；源 MAC 则用于学习。A 只有所有端口处于同一广播域时才成立，VLAN 可划分多个广播域；B 的 TCP 连接状态跟踪不是普通二层转发的必要功能；C 将交换机与共享碰撞域的集线器混淆。未知单播可按 VLAN 泛洪；组播还可能受组播侦听或过滤配置影响。'}),
950:('原图接口 MAC 首字节13为组播地址，改为有效单播12并重算；指出图中两 LAN 前缀重复。',{'prompt':'Refer to the exhibit. For this calculation, use R2 E0/1 unicast MAC address 12-be-bf-b9-00-01 (instead of the invalid group address shown). With prefix 2001:db8:bd69:1469::/64, which IPv6 address results from modified EUI-64?', 'options':[{'label':'A','text':'2001:db8:bd69:1469:12D8:BAFE:FF01:1'},{'label':'B','text':'2001:db8:bd69:1469:1130:ABFF:FECC:1'},{'label':'C','text':'2001:db8:bd69:1469:4628:255F:FE32:1'},{'label':'D','text':'2001:db8:bd69:1469:10BE:BFFF:FEB9:1'}], 'explanation':'D。将 `12:be:bf:b9:00:01` 中间插入 `ff:fe`，得 `12:be:bf:ff:fe:b9:00:01`；反转首字节的 U/L 位（`0x12 XOR 0x02 = 0x10`）得到接口 ID `10be:bfff:feb9:0001`，与 /64 前缀拼接为 `2001:db8:bd69:1469:10be:bfff:feb9:1`。原图的 `13:be:...` 首字节最低位为 1，表示组播，不能作为普通以太网接口单播 MAC；原图两个分离 LAN 又标有相同 /64，不应据此推断可路由的实际拓扑。'})}
sources=['https://www.rfc-editor.org/info/rfc8259/','https://www.rfc-editor.org/rfc/rfc4291','https://www.cisco.com/c/en/us/support/docs/lan-switching/ethernet/12006-chapter22.html','https://www.cisco.com/c/en/us/td/docs/switches/lan/c9000/lyr2-fwd/cdp-lldp-mac-udld/cdp-lldp-mac-udld-configuration-guide/configure-mac.html']
rows=[];lines=['# Q941–Q950 逐题审查','', '逐题检查题干、所有选项、答案、解析与图片/CLI。以下为人工修订依据；未进行设备实验。','']
for n,(reason,updates) in data.items():
 q=by[n];path=audit/f'exhibits/q{n}_agent.jpg';r={'id':n,'original_qid':q['qid'],'before_sha256':fp(q),'reason':reason,'updates':updates,'original_fields':{k:q.get(k) for k in updates},'has_exhibit':bool(q.get('image')),'review':{'prompt':'checked','options':'checked','answer':'checked and retained','explanation':'checked and corrected','image':'viewed' if q.get('image') else 'none required','code_cli':'checked','finding':reason}}
 if q.get('image'):r.update(exhibit_path=str(path.relative_to(audit)).replace('\\','/'),image_sha256=hashlib.sha256(path.read_bytes()).hexdigest())
 rows.append(r);lines.append(f'- Q{n}：{reason} 答案 {"、".join(q["answer"])} 保留。')
lines.extend(['','依据：']+['- '+s for s in sources]+['','原图已直接查看 Q942、Q943、Q945、Q946、Q950。'])
(audit/'agent-0941-0950.json').write_text(json.dumps({'scope':'Q941–Q950','preserve_question_ids':True,'corrections':rows,'sources':sources,'limitations':'未进行设备实验。'},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(audit/'agent-0941-0950.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Prepared',len(rows),'reviewed corrections')
